def get_tool_icon(name: str, size: int = 20) -> str:
    """Return inline SVG HTML for a tool/brand icon by name.

    Args:
        name: Tool or brand name (case-insensitive, hyphens/strips ignored)
        size: Icon size in pixels (width and height)

    Returns:
        Inline SVG string, or empty string if icon not found
    """
    key = name.lower().replace(" ", "").replace("-", "").replace(".", "")
    path = SIMPLE_ICONS.get(key, "")
    if not path:
        return ""
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">{path}</svg>'
    )


def get_tool_icon_data_uri(name: str, size: int = 20, color: str = "currentColor") -> str:
    """Return a data URI containing an SVG icon for use in CSS or img src.

    Args:
        name: Tool or brand name
        size: Icon size in pixels
        color: Fill color (default: currentColor)

    Returns:
        data:image/svg+xml,... URI string
    """
    key = name.lower().replace(" ", "").replace("-", "").replace(".", "")
    path = SIMPLE_ICONS.get(key, "")
    if not path:
        return ""
    svg = (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" fill="{escape(color)}">{path}</svg>'
    )
    import base64

    encoded = base64.b64encode(svg.encode("utf-8")).decode("ascii")
    return f"data:image/svg+xml;base64,{encoded}"
